<section class="page-heading"><span class="eyebrow">PERSONAL GUIDANCE</span><h1><?= e($title) ?></h1><p>Fictional demonstration profiles. Professional credentials are shown as verified only after an explicit administrator review.</p></section><div class="page-main"><?php if (!$data['agents']): ?><div class="empty">No approved agent profiles are available.</div><?php elseif (!$data['single']): ?><div class="profile-grid"><?php foreach ($data['agents'] as $a): ?><article class="profile-card panel"><img src="<?= e($a['photo'] ?: '/assets/favicon.svg') ?>" alt="Illustrative portrait"><div><span class="eyebrow"><?= e($a['agency']) ?></span><h3><?= e($a['name']) ?></h3><?php if ($a['verified_at']): ?><span class="verified">Admin verified · demo profile</span><?php endif ?><p><?= e($a['specialties']) ?></p><a class="text-link" href="/agent?id=<?= $a['user_id'] ?>">Meet <?= e(explode(' ',$a['name'])[0]) ?> <?= icon('arrow') ?></a></div></article><?php endforeach ?></div><?php else: $a=$data['agents'][0]; ?><div class="profile-large"><img src="<?= e($a['photo'] ?: '/assets/favicon.svg') ?>" alt="Illustrative agent portrait"><div><span class="eyebrow">DEMONSTRATION PROFILE · <?= e($a['agency']) ?></span><h2><?= e($a['name']) ?></h2><?php if ($a['verified_at']): ?><span class="verified">Admin verified · demonstration</span><?php endif ?><p><?= nl2br(e($a['biography'])) ?></p><p>Service areas: <?= e($a['service_areas']) ?><br>Languages: <?= e($a['languages']) ?><br>Specialties: <?= e($a['specialties']) ?><br>Contact preference: <?= e($a['contact_preferences']) ?></p><div class="notice">Credentials entered: <?= e($a['credentials']) ?>. <?= $a['verified_at']?'Reviewed by an administrator on '.e($a['verified_at']).' UTC.':'Credentials have not been verified.' ?></div></div></div><h2>Current homes</h2><div class="property-grid"><?php foreach (\Aurelle\Database::all('SELECT * FROM listings WHERE agent_id=? AND status IN ("published","under_offer")',[$a['user_id']]) as $p) require ROOT.'/templates/partials/property-card.php'; ?></div><h3>Recorded completed transactions</h3><p><?= (int)\Aurelle\Database::one('SELECT COUNT(*) n FROM listings WHERE agent_id=? AND status IN ("sold","rented")',[$a['user_id']])['n'] ?> platform records. Demonstration content; no real transaction claims.</p><h3>Reviews from eligible interactions</h3><?php $reviews=\Aurelle\Database::all('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.agent_id=? AND r.status="approved"',[$a['user_id']]); foreach ($reviews as $r): ?><div class="record"><b><?= e($r['name']) ?> · <?= $r['rating'] ?>/5</b><p><?= e($r['body']) ?></p></div><?php endforeach; if (!$reviews): ?><p>No approved reviews yet.</p><?php endif; endif ?></div>
